case 'buy_card': {
  let fromReserved = true;
  let card = player.cardsReserved.find(c => c.id === action.cardId);

  if (!card) {
    fromReserved = false;
    card = ([1, 2, 3] as const)
      .flatMap(level => game.boardCards[level])
      .find(c => c.id === action.cardId);
  }

  if (!card) {
    ws.send(JSON.stringify({ type: 'error', message: 'Target blueprint not found.' }));
    return;
  }

  if (action.specialTechId) {
    if (!player.specialTechIds?.includes(action.specialTechId)) {
      ws.send(JSON.stringify({ type: 'error', message: 'You do not own this Special Tech.' }));
      return;
    }
    if (player.usedSpecialTechIds?.includes(action.specialTechId)) {
      ws.send(JSON.stringify({ type: 'error', message: 'You have already used this Special Tech.' }));
      return;
    }
  }

  const validation = canBuyCard(player, card, game, { fromReserved, specialTechId: action.specialTechId });
  if (!validation.canBuy) {
    ws.send(JSON.stringify({ type: 'error', message: validation.reason || 'You cannot construct this module.' }));
    return;
  }

  undoSnapshots[gameId] = JSON.stringify(game);
  executeBuyAction(game, activeIndex, card, fromReserved, lId!, action.specialTechId);
  break;
}

